using System;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;
public static class B3CameraFix {
 public static object Survey(){var dest=SceneManager.GetActiveScene();var source=EditorSceneManager.OpenScene("Assets/Afrer_Seconds/01.Scenes/Stage/Level_B4_Circular.unity",OpenSceneMode.Additive);try{return Newtonsoft.Json.JsonConvert.SerializeObject(source.GetRootGameObjects().Select(g=>new{g.name,active=g.activeSelf,cameras=g.GetComponentsInChildren<Camera>(true).Select(c=>new{c.name,tag=c.tag,path=AnimationUtility.CalculateTransformPath(c.transform,g.transform),c.enabled}),components=g.GetComponents<Component>().Select(c=>c.GetType().FullName)}).ToArray());}finally{EditorSceneManager.CloseScene(source,true);SceneManager.SetActiveScene(dest);}}
 public static object Run(){var dest=SceneManager.GetActiveScene();if(Application.isPlaying||dest.isDirty||!dest.path.EndsWith("Level_B3_Circular.unity"))throw new Exception("Saved B3 required");var source=EditorSceneManager.OpenScene("Assets/Afrer_Seconds/01.Scenes/Stage/Level_B4_Circular.unity",OpenSceneMode.Additive);int count=0,refs=0;var cameraRoots=new System.Collections.Generic.Dictionary<Transform,Transform>();try{var originalPlayer=source.GetRootGameObjects().Single(g=>g.name.StartsWith("Player"));var targetPlayer=dest.GetRootGameObjects().Single(g=>g.name.StartsWith("Player"));var roots=source.GetRootGameObjects().Where(g=>g!=originalPlayer&&(g.GetComponentsInChildren<Camera>(true).Length>0||g.GetComponentsInChildren<Component>(true).Any(c=>c&&c.GetType().Name.Contains("CinemachineCamera")))).ToArray();SceneManager.SetActiveScene(dest);foreach(var original in roots){if(dest.GetRootGameObjects().Any(g=>g.name==original.name))throw new Exception("Root already exists "+original.name);var clone=UnityEngine.Object.Instantiate(original);clone.name=original.name;cameraRoots[original.transform]=clone.transform;SceneManager.MoveGameObjectToScene(clone,dest);foreach(var comp in clone.GetComponentsInChildren<Component>(true)){if(!comp)continue;var so=new SerializedObject(comp);var it=so.GetIterator();while(it.Next(true)){if(it.propertyType!=SerializedPropertyType.ObjectReference||!it.objectReferenceValue)continue;var ob=it.objectReferenceValue;var tr=ob is GameObject go?go.transform:ob is Component co?co.transform:null;if(!tr||!tr.IsChildOf(originalPlayer.transform)&&tr!=originalPlayer.transform)continue;string path=AnimationUtility.CalculateTransformPath(tr,originalPlayer.transform);var target=path==""?targetPlayer.transform:targetPlayer.transform.Find(path);if(!target)throw new Exception("Unmapped camera reference "+path);it.objectReferenceValue=ob is GameObject?target.gameObject:target.GetComponent(ob.GetType());refs++;}so.ApplyModifiedPropertiesWithoutUndo();}foreach(var c in clone.GetComponentsInChildren<Camera>(true))c.useOcclusionCulling=true;count++;}foreach(var targetComp in targetPlayer.GetComponentsInChildren<Component>(true)){if(!targetComp)continue;string rel=AnimationUtility.CalculateTransformPath(targetComp.transform,targetPlayer.transform);var origTr=rel==""?originalPlayer.transform:originalPlayer.transform.Find(rel);var origComp=origTr.GetComponent(targetComp.GetType());if(!origComp)continue;var originalSO=new SerializedObject(origComp);var targetSO=new SerializedObject(targetComp);var it=originalSO.GetIterator();while(it.Next(true)){if(it.propertyType!=SerializedPropertyType.ObjectReference||!it.objectReferenceValue)continue;var ob=it.objectReferenceValue;var tr=ob is GameObject go?go.transform:ob is Component co?co.transform:null;if(!tr)continue;var pair=cameraRoots.FirstOrDefault(k=>tr==k.Key||tr.IsChildOf(k.Key));if(!pair.Key)continue;string path=AnimationUtility.CalculateTransformPath(tr,pair.Key);var target=path==""?pair.Value:pair.Value.Find(path);var dst=targetSO.FindProperty(it.propertyPath);if(dst==null||!target)throw new Exception("Unmapped player camera property "+it.propertyPath);dst.objectReferenceValue=ob is GameObject?target.gameObject:target.GetComponent(ob.GetType());refs++;}targetSO.ApplyModifiedPropertiesWithoutUndo();PrefabUtility.RecordPrefabInstancePropertyModifications(targetComp);}EditorSceneManager.MarkSceneDirty(dest);EditorSceneManager.SaveScene(dest);}finally{EditorSceneManager.CloseScene(source,true);SceneManager.SetActiveScene(dest);}return new{copiedCameraRoots=count,remappedPlayerReferences=refs,cameras=dest.GetRootGameObjects().Sum(g=>g.GetComponentsInChildren<Camera>(true).Length)};}
}
